/** Manual, keyboard-operable player showcase; figures are official squad snapshots. */
?>
<?php if($players): ?><section class="spotlight" aria-label="世界杯球员展示"><?php foreach(array_slice($players,0,3) as $i=>$p): ?><article id="spotlight-<?= (int)$i ?>" class="spotlight-slide <?= $i===0?'is-active':'' ?>" data-spotlight-slide role="tabpanel" aria-labelledby="spotlight-tab-<?= (int)$i ?>" <?= $i?'hidden':'' ?>><span class="spotlight-mark" aria-hidden="true"><?= e($p->team?->code) ?></span><div class="spotlight-copy"><span class="meta"><?= \app\services\TeamUi::label($p->team) ?> / <?= e(['GK'=>'守门员','DF'=>'后卫','MF'=>'中场','FW'=>'前锋'][$p->position]??$p->position) ?> / #<?= (int)$p->shirt_number ?></span><h2><?= e($p->name) ?></h2><p><?= e($p->club?:'FIFA 官方阵容') ?> · <?= e($p->height_cm??'—') ?> 厘米</p><div class="spotlight-facts"><div><b><?= e($p->caps??'—') ?></b><small>国家队出场</small></div><div><b><?= e($p->goals??'—') ?></b><small>国家队进球</small></div><div><b><?= (int)$p->shirt_number ?></b><small>球衣号码</small></div></div><a class="button lime" href="/players/<?= e($p->slug) ?>">查看球员资料 ↗</a></div><?php if($p->photo_url): ?><img class="spotlight-photo" src="<?= e(safe_url($p->displayPhotoUrl)) ?>" alt="<?= e($p->name_original) ?> · FIFA 官方照片" referrerpolicy="no-referrer"><?php endif ?></article><?php endforeach ?><div class="spotlight-tabs" role="tablist" aria-label="切换展示球员"><?php foreach(array_slice($players,0,3) as $i=>$p): ?><button type="button" id="spotlight-tab-<?= (int)$i ?>" role="tab" aria-selected="<?= $i===0?'true':'false' ?>" aria-controls="spotlight-<?= (int)$i ?>" tabindex="<?= $i===0?'0':'-1' ?>" data-spotlight-tab><?= str_pad((string)($i+1),2,'0',STR_PAD_LEFT) ?> / <?= e($p->name) ?></button><?php endforeach ?></div></section><?php endif ?>
